INSERT INTO Exercise (slug,payload) VALUES ('incline-dumbbell-press','{"slug":"incline-dumbbell-press","name":"Incline dumbbell press","muscles":["Chest","Triceps","Front shoulders"],"instructions":["Sit on an incline bench with a dumbbell in each hand.","Keep your feet stable and your shoulder blades against the bench.","Lower the weights beside your upper chest.","Press the weights above your shoulders without striking them together."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/incline-dumbbell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/25/incline-chest-press/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
