INSERT INTO Exercise (slug,payload) VALUES ('barbell-romanian-deadlift','{"slug":"barbell-romanian-deadlift","name":"Barbell Romanian deadlift","muscles":["Hamstrings","Glutes"],"instructions":["Stand with the bar at your thighs and knees slightly bent.","Push your hips back and keep the bar close to your legs.","Lower only as far as you can keep your back stable.","Drive your hips forward to stand. Do not lean back."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-romanian-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/romanian-deadlift-barbell"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
