INSERT INTO Exercise (slug,payload) VALUES ('ez-bar-curl','{"slug":"ez-bar-curl","name":"EZ-bar curl","muscles":["Biceps"],"instructions":["Grip the angled parts of the bar with palms facing upward.","Keep your elbows beside your trunk.","Curl the bar without moving your shoulders forward.","Lower with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/ez-bar-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/70/bicep-curl/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('one-arm-kettlebell-row','{"slug":"one-arm-kettlebell-row","name":"One-arm kettlebell row","muscles":["Back","Biceps"],"instructions":["Hinge at the hips and support your free hand.","Let the kettlebell hang below your shoulder.","Pull the bell towards your lower ribs without rotating your trunk.","Lower and repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/one-arm-kettlebell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/568/Single-Arm-Dumbbell-Row/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('strict-kettlebell-press','{"slug":"strict-kettlebell-press","name":"Strict kettlebell press","muscles":["Shoulders","Triceps"],"instructions":["Hold one kettlebell in the rack beside your shoulder.","Keep the wrist straight and the bell against the forearm.","Press overhead with no leg drive.","Lower to the rack with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/strict-kettlebell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/395/single-arm-overhead-press/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('kettlebell-goblet-squat','{"slug":"kettlebell-goblet-squat","name":"Kettlebell goblet squat","muscles":["Quadriceps","Glutes"],"instructions":["Hold one bell close to your chest with both hands.","Brace your trunk and keep heels grounded.","Bend your hips and knees into a controlled squat.","Stand while keeping the bell close to your chest."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/kettlebell-goblet-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/goblet-squat"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('two-hand-kettlebell-swing','{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('barbell-deadlift','{"slug":"barbell-deadlift","name":"Barbell deadlift","muscles":["Glutes","Hamstrings","Back"],"instructions":["Stand with the bar over midfoot, close to your shins.","Bend at hips and knees to grip the bar and brace your trunk.","Push through the floor and stand with the bar close to your legs.","Return the bar by moving your hips back, then bending your knees."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/6/deadlift/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('trap-bar-deadlift','{"slug":"trap-bar-deadlift","name":"Trap-bar deadlift","muscles":["Glutes","Quadriceps","Back"],"instructions":["Stand in the centre of the trap bar.","Bend hips and knees to grip both handles.","Brace your trunk and stand with the handles at your sides.","Lower the bar with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/trap-bar-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://theprehabguys.com/vimeo-video/hex-bar-vs-barbell-deadlift-knowing-the-difference/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('push-up','{"slug":"push-up","name":"Push-up","muscles":["Chest","Triceps","Trunk"],"instructions":["Start in a high plank with hands near shoulder width.","Keep your trunk and hips in one line.","Bend your elbows to lower your chest towards the floor.","Press up without letting your hips sag."],"equipment":"Bodyweight","loadBasis":"bodyweight","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/push-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/push-up"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('double-kettlebell-front-squat','{"slug":"double-kettlebell-front-squat","name":"Double kettlebell front squat","muscles":["Quadriceps","Glutes"],"instructions":["Rack one bell beside each shoulder with straight wrists.","Keep elbows near your trunk and brace your body.","Squat with heels grounded and both bells held in the rack.","Stand with the bells still in the rack. Count one rep for the paired movement."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/double-kettlebell-front-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/kettlebell-front-squat"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('single-kettlebell-clean-and-press','{"slug":"single-kettlebell-clean-and-press","name":"Single kettlebell clean and press","muscles":["Glutes","Shoulders","Triceps"],"instructions":["Hinge and hike one bell between your legs.","Extend your hips and guide the bell close to your body into the rack. Do not flip it onto your wrist.","Pause in the rack with a straight wrist.","Press overhead, then lower to the rack and return to the hinge. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/single-kettlebell-clean-and-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/383/clean-and-press/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('double-kettlebell-clean-and-press','{"slug":"double-kettlebell-clean-and-press","name":"Double kettlebell clean and press","muscles":["Glutes","Shoulders","Triceps"],"instructions":["Hinge and hike both bells between your legs.","Extend your hips and guide both bells close into the front rack.","Pause with straight wrists and a stable trunk.","Press both bells overhead. Return to the rack, then the hinge. Count one rep for the pair."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/double-kettlebell-clean-and-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/3-cleans-relationship-form-function/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO Exercise (slug,payload) VALUES ('turkish-get-up','{"slug":"turkish-get-up","name":"Turkish get-up","muscles":["Shoulders","Trunk","Glutes"],"instructions":["Lie on your back with the bell in your right hand, right arm vertical, right knee bent and left leg extended.","Roll to your left elbow while keeping the bell above your shoulder.","Press onto your left hand.","Raise your hips to make space for your left leg.","Sweep the left knee under your hips to a supported kneeling position.","Lift your left hand and align into an upright half-kneel.","Stand. Reverse each step with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/turkish-get-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"}') ON CONFLICT(slug) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-1-day-1',1,'{"id":"phase-1-day-1","revision":1,"phase":1,"dayIndex":1,"title":"Chest & Triceps","notes":"Build technique and a base. Keep kettlebell finishers light.","exercises":[{"exercise":{"slug":"incline-barbell-press","name":"Incline barbell press","muscles":["Chest","Triceps","Front shoulders"],"instructions":["Set the bench to a moderate incline and keep both feet on the floor.","Grip the bar slightly wider than your shoulders. Keep your wrists above your elbows.","Lower the bar towards your upper chest with control.","Press above your chest. Keep your hips on the bench."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/incline-barbell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/incline-barbell-bench-press"},"alternatives":["incline-dumbbell-press"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"flat-barbell-bench-press","name":"Flat barbell bench press","muscles":["Chest","Triceps"],"instructions":["Lie on a flat bench. Keep your feet on the floor.","Grip the bar with wrists above your elbows.","Lower towards your chest with control.","Press up and keep your hips on the bench."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/flat-barbell-bench-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/5/chest-press/"},"alternatives":["parallel-bar-dips"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"dumbbell-fly","name":"Dumbbell fly","muscles":["Chest"],"instructions":["Lie on a flat bench with the weights above your chest.","Keep a slight bend in both elbows.","Open your arms to a comfortable range without forcing a stretch.","Bring the weights back above your chest with the same elbow bend."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/dumbbell-fly.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/21/lying-chest-fly/"},"alternatives":["pec-deck"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"triceps-pushdown","name":"Triceps pushdown","muscles":["Triceps"],"instructions":["Stand facing a high cable with elbows beside your ribs.","Start with bent elbows and wrists straight.","Extend your elbows and press the handle down.","Return without moving your upper arms forward."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/triceps-pushdown.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://yogiathletics.com/library/triceps-pushdown"},"alternatives":["overhead-dumbbell-extension"],"setMin":1,"setMax":2,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"kettlebell-goblet-squat","name":"Kettlebell goblet squat","muscles":["Quadriceps","Glutes"],"instructions":["Hold one bell close to your chest with both hands.","Brace your trunk and keep heels grounded.","Bend your hips and knees into a controlled squat.","Stand while keeping the bell close to your chest."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/kettlebell-goblet-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/goblet-squat"},"alternatives":["two-hand-kettlebell-swing"],"setMin":2,"setMax":2,"repMin":10,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"Light finisher."}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
