ith elbows near your sides.","Press up with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/close-grip-bench-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/311/close-grip-bench-press/"},"alternatives":["parallel-bar-dips"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"hammer-curl","name":"Hammer curl","muscles":["Biceps","Forearms"],"instructions":["Stand with dumbbells at your sides and palms facing inward.","Keep elbows beside your trunk.","Curl the weights with palms still facing inward.","Lower without swinging."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/hammer-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/10/hammer-curl/"},"alternatives":["ez-bar-curl"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"strict-kettlebell-press","name":"Strict kettlebell press","muscles":["Shoulders","Triceps"],"instructions":["Hold one kettlebell in the rack beside your shoulder.","Keep the wrist straight and the bell against the forearm.","Press overhead with no leg drive.","Lower to the rack with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/strict-kettlebell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/395/single-arm-overhead-press/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":6,"repMax":8,"optional":false,"circuitGroup":null,"restSeco