INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-1-day-5',1,'{"id":"phase-1-day-5","revision":1,"phase":1,"dayIndex":5,"title":"Full Body","notes":"Build technique and a base. Keep kettlebell finishers light.","exercises":[{"exercise":{"slug":"barbell-deadlift","name":"Barbell deadlift","muscles":["Glutes","Hamstrings","Back"],"instructions":["Stand with the bar over midfoot, close to your shins.","Bend at hips and knees to grip the bar and brace your trunk.","Push through the floor and stand with the bar close to your legs.","Return the bar by moving your hips back, then bending your knees."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/6/deadlift/"},"alternatives":["trap-bar-deadlift"],"setMin":1,"setMax":1,"repMin":5,"repMax":8,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"incline-dumbbell-press","name":"Incline dumbbell press","muscles":["Chest","Triceps","Front shoulders"],"instructions":["Sit on an incline bench with a dumbbell in each hand.","Keep your feet stable and your shoulder blades against the bench.","Lower the weights beside your upper chest.","Press the weights above your shoulders without striking them together."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/incline-dumbbell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/25/incline-chest-press/"},"alternatives":["push-up"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"barbell-row","name":"Barbell row","muscles":["Back","Biceps"],"instructions":["Hinge at your hips with a slight knee bend.","Keep your back stable and let the bar hang below your shoulders.","Pull the bar towards your lower ribs.","Lower the bar without changing your trunk angle."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/12/bent-over-row/"},"alternatives":["one-arm-dumbbell-row"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":2,"setMax":3,"repMin":null,"repMax":null,"optional":false,"circuitGroup":"kb-circuit","restSeconds":180,"notes":"2–3 circuit rounds. Reps are free to log."},{"exercise":{"slug":"kettlebell-goblet-squat","name":"Kettlebell goblet squat","muscles":["Quadriceps","Glutes"],"instructions":["Hold one bell close to your chest with both hands.","Brace your trunk and keep heels grounded.","Bend your hips and knees into a controlled squat.","Stand while keeping the bell close to your chest."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/kettlebell-goblet-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/goblet-squat"},"alternatives":[],"setMin":2,"setMax":3,"repMin":null,"repMax":null,"optional":false,"circuitGroup":"kb-circuit","restSeconds":180,"notes":"2–3 circuit rounds. Reps are free to log."},{"exercise":{"slug":"one-arm-kettlebell-row","name":"One-arm kettlebell row","muscles":["Back","Biceps"],"instructions":["Hinge at the hips and support your free hand.","Let the kettlebell hang below your shoulder.","Pull the bell towards your lower ribs without rotating your trunk.","Lower and repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/one-arm-kettlebell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/568/Single-Arm-Dumbbell-Row/"},"alternatives":["strict-kettlebell-press"],"setMin":2,"setMax":3,"repMin":null,"repMax":null,"optional":false,"circuitGroup":"kb-circuit","restSeconds":180,"notes":"2–3 circuit rounds. Reps are free to log."}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
