INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-2-day-1',1,'{"id":"phase-2-day-1","revision":1,"phase":2,"dayIndex":1,"title":"Chest & Triceps","notes":"Supplied intensity note: increase weight or reps when form is solid. Optional rest-pause: rest 10–15 seconds, then 2–4 more reps. This is optional, not an automatic load or timer change.","exercises":[{"exercise":{"slug":"incline-barbell-press","name":"Incline barbell press","muscles":["Chest","Triceps","Front shoulders"],"instructions":["Set the bench to a moderate incline and keep both feet on the floor.","Grip the bar slightly wider than your shoulders. Keep your wrists above your elbows.","Lower the bar towards your upper chest with control.","Press above your chest. Keep your hips on the bench."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/incline-barbell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/incline-barbell-bench-press"},"alternatives":["incline-dumbbell-press"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"flat-barbell-bench-press","name":"Flat barbell bench press","muscles":["Chest","Triceps"],"instructions":["Lie on a flat bench. Keep your feet on the floor.","Grip the bar with wrists above your elbows.","Lower towards your chest with control.","Press up and keep your hips on the bench."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/flat-barbell-bench-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/5/chest-press/"},"alternatives":["parallel-bar-dips"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"dumbbell-fly","name":"Dumbbell fly","muscles":["Chest"],"instructions":["Lie on a flat bench with the weights above your chest.","Keep a slight bend in both elbows.","Open your arms to a comfortable range without forcing a stretch.","Bring the weights back above your chest with the same elbow bend."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/dumbbell-fly.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/21/lying-chest-fly/"},"alternatives":["pec-deck"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"triceps-pushdown","name":"Triceps pushdown","muscles":["Triceps"],"instructions":["Stand facing a high cable with elbows beside your ribs.","Start with bent elbows and wrists straight.","Extend your elbows and press the handle down.","Return without moving your upper arms forward."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/triceps-pushdown.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://yogiathletics.com/library/triceps-pushdown"},"alternatives":["overhead-dumbbell-extension"],"setMin":1,"setMax":2,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"kettlebell-goblet-squat","name":"Kettlebell goblet squat","muscles":["Quadriceps","Glutes"],"instructions":["Hold one bell close to your chest with both hands.","Brace your trunk and keep heels grounded.","Bend your hips and knees into a controlled squat.","Stand while keeping the bell close to your chest."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/kettlebell-goblet-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/goblet-squat"},"alternatives":["two-hand-kettlebell-swing"],"setMin":2,"setMax":2,"repMin":10,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"Light finisher."}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
