INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-2-day-1-2','phase-2-day-1',2,'{"exercise":{"slug":"dumbbell-fly","name":"Dumbbell fly","muscles":["Chest"],"instructions":["Lie on a flat bench with the weights above your chest.","Keep a slight bend in both elbows.","Open your arms to a comfortable range without forcing a stretch.","Bring the weights back above your chest with the same elbow bend."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/dumbbell-fly.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/21/lying-chest-fly/"},"alternatives":["pec-deck"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-2-day-1-3','phase-2-day-1',3,'{"exercise":{"slug":"triceps-pushdown","name":"Triceps pushdown","muscles":["Triceps"],"instructions":["Stand facing a high cable with elbows beside your ribs.","Start with bent elbows and wrists straight.","Extend your elbows and press the handle down.","Return without moving your upper arms forward."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/triceps-pushdown.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://yogiathletics.com/library/triceps-pushdown"},"alternatives":["overhead-dumbbell-extension"],"setMin":1,"setMax":2,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-2-day-1-4','phase-2-day-1',4,'{"exercise":{"slug":"kettlebell-goblet-squat","name":"Kettlebell goblet squat","muscles":["Quadriceps","Glutes"],"instructions":["Hold one bell close to your chest with both hands.","Brace your trunk and keep heels grounded.","Bend your hips and knees into a controlled squat.","Stand while keeping the bell close to your chest."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/kettlebell-goblet-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/goblet-squat"},"alternatives":["two-hand-kettlebell-swing"],"setMin":2,"setMax":2,"repMin":10,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"Light finisher."}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-2-day-2',1,'{"id":"phase-2-day-2","revision":1,"phase":2,"dayIndex":2,"title":"Back & Biceps","notes":"Supplied intensity note: increase weight or reps when form is solid. Optional rest-pause: rest 10–15 seconds, then 2–4 more reps. This is optional, not an automatic load or timer change.","exercises":[{"exercise":{"slug":"pull-up","name":"Pull-up","muscles":["Back","Biceps"],"instructions":["Grip an overhead bar and hang with a controlled shoulder position.","Pull your elbows down as you raise your body.","Bring your chin above the bar without reaching your neck forward.","Lower with control."],"equipment":"Bodyweight","loadBasis":"bodyweight","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/pull-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/pull-up"},"alternatives":["lat-pulldown"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"barbell-row","name":"Barbell row","muscles":["Back","Biceps"],"instructions":["Hinge at your hips with a slight knee bend.","Keep your back stable and let the bar hang below your shoulders.","Pull the bar towards your lower ribs.","Lower the bar without changing your trunk angle."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/12/bent-over-row/"},"alternatives":["one-arm-dumbbell-row"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"face-pull","name":"Face pull","muscles":["Rear shoulders","Upper back"],"instructions":["Set a rope cable near face height.","Stand stable and hold the rope with arms extended.","Pull the rope towards your face and separate your hands.","Return with control without leaning back."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/face-pull.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/767/Face-Pull/"},"alternatives":["dumbbell-rear-delt-fly"],"setMin":1,"setMax":1,"repMin":12,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"barbell-curl","name":"Barbell curl","muscles":["Biceps"],"instructions":["Stand with the bar at your thighs, palms forward.","Keep your elbows beside your trunk.","Bend your elbows to raise the bar.","Lower without swinging your body."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/70/bicep-curl/"},"alternatives":["dumbbell-curl"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"one-arm-kettlebell-row","name":"One-arm kettlebell row","muscles":["Back","Biceps"],"instructions":["Hinge at the hips and support your free hand.","Let the kettlebell hang below your shoulder.","Pull the bell towards your lower ribs without rotating your trunk.","Lower and repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/one-arm-kettlebell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/568/Single-Arm-Dumbbell-Row/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":8,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
