INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-2-day-3',1,'{"id":"phase-2-day-3","revision":1,"phase":2,"dayIndex":3,"title":"Legs","notes":"Supplied intensity note: increase weight or reps when form is solid. Optional rest-pause: rest 10–15 seconds, then 2–4 more reps. This is optional, not an automatic load or timer change.","exercises":[{"exercise":{"slug":"barbell-back-squat","name":"Barbell back squat","muscles":["Quadriceps","Glutes"],"instructions":["Place the bar across your upper back, clear of your neck.","Stand with a stable foot position and brace your trunk.","Bend your hips and knees while keeping heels grounded.","Stand up with knees aligned with your feet."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-back-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/11/back-squat/"},"alternatives":["leg-press"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"barbell-romanian-deadlift","name":"Barbell Romanian deadlift","muscles":["Hamstrings","Glutes"],"instructions":["Stand with the bar at your thighs and knees slightly bent.","Push your hips back and keep the bar close to your legs.","Lower only as far as you can keep your back stable.","Drive your hips forward to stand. Do not lean back."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-romanian-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/romanian-deadlift-barbell"},"alternatives":[],"setMin":1,"setMax":2,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"leg-extension","name":"Leg extension","muscles":["Quadriceps"],"instructions":["Align your knees with the machine pivot.","Place the roller above your ankles and hold the handles.","Extend your knees with control.","Lower the roller without lifting your hips."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/leg-extension.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/183/seated-leg-extension/"},"alternatives":["kettlebell-goblet-squat"],"setMin":1,"setMax":1,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"standing-barbell-calf-raise","name":"Standing barbell calf raise","muscles":["Calves"],"instructions":["Secure the bar on your upper back and use a stable support setup.","Place the balls of your feet on the step.","Raise your heels while keeping your knees stable.","Lower your heels with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/standing-barbell-calf-raise.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/51/calf-raises/"},"alternatives":[],"setMin":1,"setMax":2,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"Light to moderate."}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
