INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-2-day-4-2','phase-2-day-4',2,'{"exercise":{"slug":"close-grip-bench-press","name":"Close-grip bench press","muscles":["Triceps","Chest"],"instructions":["Lie on a flat bench with feet grounded.","Use a grip near shoulder width and keep wrists stable.","Lower the bar towards your chest with elbows near your sides.","Press up with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/close-grip-bench-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/311/close-grip-bench-press/"},"alternatives":["parallel-bar-dips"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-2-day-4-3','phase-2-day-4',3,'{"exercise":{"slug":"hammer-curl","name":"Hammer curl","muscles":["Biceps","Forearms"],"instructions":["Stand with dumbbells at your sides and palms facing inward.","Keep elbows beside your trunk.","Curl the weights with palms still facing inward.","Lower without swinging."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/hammer-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/10/hammer-curl/"},"alternatives":["ez-bar-curl"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-2-day-4-4','phase-2-day-4',4,'{"exercise":{"slug":"strict-kettlebell-press","name":"Strict kettlebell press","muscles":["Shoulders","Triceps"],"instructions":["Hold one kettlebell in the rack beside your shoulder.","Keep the wrist straight and the bell against the forearm.","Press overhead with no leg drive.","Lower to the rack with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/strict-kettlebell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/395/single-arm-overhead-press/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":6,"repMax":8,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-2-day-5',1,'{"id":"phase-2-day-5","revision":1,"phase":2,"dayIndex":5,"title":"Full Body","notes":"Supplied intensity note: increase weight or reps when form is solid. Optional rest-pause: rest 10–15 seconds, then 2–4 more reps. This is optional, not an automatic load or timer change.","exercises":[{"exercise":{"slug":"barbell-deadlift","name":"Barbell deadlift","muscles":["Glutes","Hamstrings","Back"],"instructions":["Stand with the bar over midfoot, close to your shins.","Bend at hips and knees to grip the bar and brace your trunk.","Push through the floor and stand with the bar close to your legs.","Return the bar by moving your hips back, then bending your knees."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/6/deadlift/"},"alternatives":["barbell-back-squat"],"setMin":1,"setMax":1,"repMin":null,"repMax":null,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"single-kettlebell-clean-and-press","name":"Single kettlebell clean and press","muscles":["Glutes","Shoulders","Triceps"],"instructions":["Hinge and hike one bell between your legs.","Extend your hips and guide the bell close to your body into the rack. Do not flip it onto your wrist.","Pause in the rack with a straight wrist.","Press overhead, then lower to the rack and return to the hinge. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/single-kettlebell-clean-and-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/383/clean-and-press/"},"alternatives":[],"setMin":3,"setMax":3,"repMin":4,"repMax":8,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":3,"setMax":3,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"turkish-get-up","name":"Turkish get-up","muscles":["Shoulders","Trunk","Glutes"],"instructions":["Lie on your back with the bell in your right hand, right arm vertical, right knee bent and left leg extended.","Roll to your left elbow while keeping the bell above your shoulder.","Press onto your left hand.","Raise your hips to make space for your left leg.","Sweep the left knee under your hips to a supported kneeling position.","Lift your left hand and align into an upright half-kneel.","Stand. Reverse each step with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/turkish-get-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":null,"setMax":null,"repMin":null,"repMax":null,"optional":true,"circuitGroup":null,"restSeconds":180,"notes":"Very light practice."}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
