INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-3-day-2',1,'{"id":"phase-3-day-2","revision":1,"phase":3,"dayIndex":2,"title":"Back & Biceps","notes":"Supplied peak note: one all-out set for main compounds, with optional rest-pause. Keep accessory targets from Foundation.","exercises":[{"exercise":{"slug":"pull-up","name":"Pull-up","muscles":["Back","Biceps"],"instructions":["Grip an overhead bar and hang with a controlled shoulder position.","Pull your elbows down as you raise your body.","Bring your chin above the bar without reaching your neck forward.","Lower with control."],"equipment":"Bodyweight","loadBasis":"bodyweight","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/pull-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/pull-up"},"alternatives":["lat-pulldown"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."},{"exercise":{"slug":"barbell-row","name":"Barbell row","muscles":["Back","Biceps"],"instructions":["Hinge at your hips with a slight knee bend.","Keep your back stable and let the bar hang below your shoulders.","Pull the bar towards your lower ribs.","Lower the bar without changing your trunk angle."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/12/bent-over-row/"},"alternatives":["one-arm-dumbbell-row"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."},{"exercise":{"slug":"face-pull","name":"Face pull","muscles":["Rear shoulders","Upper back"],"instructions":["Set a rope cable near face height.","Stand stable and hold the rope with arms extended.","Pull the rope towards your face and separate your hands.","Return with control without leaning back."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/face-pull.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/767/Face-Pull/"},"alternatives":["dumbbell-rear-delt-fly"],"setMin":1,"setMax":1,"repMin":12,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"barbell-curl","name":"Barbell curl","muscles":["Biceps"],"instructions":["Stand with the bar at your thighs, palms forward.","Keep your elbows beside your trunk.","Bend your elbows to raise the bar.","Lower without swinging your body."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/70/bicep-curl/"},"alternatives":["dumbbell-curl"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"one-arm-kettlebell-row","name":"One-arm kettlebell row","muscles":["Back","Biceps"],"instructions":["Hinge at the hips and support your free hand.","Let the kettlebell hang below your shoulder.","Pull the bell towards your lower ribs without rotating your trunk.","Lower and repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/one-arm-kettlebell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/568/Single-Arm-Dumbbell-Row/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":8,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-2-0','phase-3-day-2',0,'{"exercise":{"slug":"pull-up","name":"Pull-up","muscles":["Back","Biceps"],"instructions":["Grip an overhead bar and hang with a controlled shoulder position.","Pull your elbows down as you raise your body.","Bring your chin above the bar without reaching your neck forward.","Lower with control."],"equipment":"Bodyweight","loadBasis":"bodyweight","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/pull-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/pull-up"},"alternatives":["lat-pulldown"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
