INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-2-2','phase-3-day-2',2,'{"exercise":{"slug":"face-pull","name":"Face pull","muscles":["Rear shoulders","Upper back"],"instructions":["Set a rope cable near face height.","Stand stable and hold the rope with arms extended.","Pull the rope towards your face and separate your hands.","Return with control without leaning back."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/face-pull.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/767/Face-Pull/"},"alternatives":["dumbbell-rear-delt-fly"],"setMin":1,"setMax":1,"repMin":12,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-2-3','phase-3-day-2',3,'{"exercise":{"slug":"barbell-curl","name":"Barbell curl","muscles":["Biceps"],"instructions":["Stand with the bar at your thighs, palms forward.","Keep your elbows beside your trunk.","Bend your elbows to raise the bar.","Lower without swinging your body."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/70/bicep-curl/"},"alternatives":["dumbbell-curl"],"setMin":1,"setMax":2,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-2-4','phase-3-day-2',4,'{"exercise":{"slug":"one-arm-kettlebell-row","name":"One-arm kettlebell row","muscles":["Back","Biceps"],"instructions":["Hinge at the hips and support your free hand.","Let the kettlebell hang below your shoulder.","Pull the bell towards your lower ribs without rotating your trunk.","Lower and repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/one-arm-kettlebell-row.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.catalystathletics.com/exercise/568/Single-Arm-Dumbbell-Row/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":8,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-3-day-3',1,'{"id":"phase-3-day-3","revision":1,"phase":3,"dayIndex":3,"title":"Legs","notes":"Supplied peak note: one all-out set for main compounds, with optional rest-pause. Keep accessory targets from Foundation.","exercises":[{"exercise":{"slug":"barbell-back-squat","name":"Barbell back squat","muscles":["Quadriceps","Glutes"],"instructions":["Place the bar across your upper back, clear of your neck.","Stand with a stable foot position and brace your trunk.","Bend your hips and knees while keeping heels grounded.","Stand up with knees aligned with your feet."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-back-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/11/back-squat/"},"alternatives":["leg-press"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."},{"exercise":{"slug":"barbell-romanian-deadlift","name":"Barbell Romanian deadlift","muscles":["Hamstrings","Glutes"],"instructions":["Stand with the bar at your thighs and knees slightly bent.","Push your hips back and keep the bar close to your legs.","Lower only as far as you can keep your back stable.","Drive your hips forward to stand. Do not lean back."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-romanian-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/romanian-deadlift-barbell"},"alternatives":[],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."},{"exercise":{"slug":"leg-extension","name":"Leg extension","muscles":["Quadriceps"],"instructions":["Align your knees with the machine pivot.","Place the roller above your ankles and hold the handles.","Extend your knees with control.","Lower the roller without lifting your hips."],"equipment":"Machine","loadBasis":"machine","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/leg-extension.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/183/seated-leg-extension/"},"alternatives":["kettlebell-goblet-squat"],"setMin":1,"setMax":1,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"standing-barbell-calf-raise","name":"Standing barbell calf raise","muscles":["Calves"],"instructions":["Secure the bar on your upper back and use a stable support setup.","Place the balls of your feet on the step.","Raise your heels while keeping your knees stable.","Lower your heels with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/standing-barbell-calf-raise.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/51/calf-raises/"},"alternatives":[],"setMin":1,"setMax":2,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"Light to moderate."}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
