INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-3-day-4',1,'{"id":"phase-3-day-4","revision":1,"phase":3,"dayIndex":4,"title":"Shoulders & Arms","notes":"Supplied peak note: one all-out set for main compounds, with optional rest-pause. Keep accessory targets from Foundation.","exercises":[{"exercise":{"slug":"barbell-overhead-press","name":"Barbell overhead press","muscles":["Shoulders","Triceps"],"instructions":["Stand with the bar at your upper chest.","Brace your trunk and keep knees steady.","Press the bar overhead, moving your head clear of its path.","Lower to your upper chest with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-overhead-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://mail.catalystathletics.com/article/1912/The-Press-for-Weightlifting-How-Useful-Is-It/"},"alternatives":["seated-dumbbell-overhead-press"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."},{"exercise":{"slug":"dumbbell-lateral-raise","name":"Dumbbell lateral raise","muscles":["Side shoulders"],"instructions":["Stand with the weights beside your thighs.","Keep elbows slightly bent.","Raise your arms out to about shoulder height.","Lower without swinging."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/dumbbell-lateral-raise.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/26/lateral-raise/"},"alternatives":[],"setMin":1,"setMax":2,"repMin":10,"repMax":15,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"close-grip-bench-press","name":"Close-grip bench press","muscles":["Triceps","Chest"],"instructions":["Lie on a flat bench with feet grounded.","Use a grip near shoulder width and keep wrists stable.","Lower the bar towards your chest with elbows near your sides.","Press up with control."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/close-grip-bench-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/311/close-grip-bench-press/"},"alternatives":["parallel-bar-dips"],"setMin":1,"setMax":1,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":"One all-out set; optional rest-pause (supplied plan note)."},{"exercise":{"slug":"hammer-curl","name":"Hammer curl","muscles":["Biceps","Forearms"],"instructions":["Stand with dumbbells at your sides and palms facing inward.","Keep elbows beside your trunk.","Curl the weights with palms still facing inward.","Lower without swinging."],"equipment":"Dumbbell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/hammer-curl.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/10/hammer-curl/"},"alternatives":["ez-bar-curl"],"setMin":1,"setMax":1,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"strict-kettlebell-press","name":"Strict kettlebell press","muscles":["Shoulders","Triceps"],"instructions":["Hold one kettlebell in the rack beside your shoulder.","Keep the wrist straight and the bell against the forearm.","Press overhead with no leg drive.","Lower to the rack with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/strict-kettlebell-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/395/single-arm-overhead-press/"},"alternatives":[],"setMin":2,"setMax":2,"repMin":6,"repMax":8,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
