INSERT INTO PlanTemplate (id,revision,payload) VALUES ('phase-3-day-5',1,'{"id":"phase-3-day-5","revision":1,"phase":3,"dayIndex":5,"title":"Full Body","notes":"Supplied peak note: one all-out set for main compounds, with optional rest-pause. Keep accessory targets from Foundation.","exercises":[{"exercise":{"slug":"barbell-deadlift","name":"Barbell deadlift","muscles":["Glutes","Hamstrings","Back"],"instructions":["Stand with the bar over midfoot, close to your shins.","Bend at hips and knees to grip the bar and brace your trunk.","Push through the floor and stand with the bar close to your legs.","Return the bar by moving your hips back, then bending your knees."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/6/deadlift/"},"alternatives":["barbell-back-squat"],"setMin":1,"setMax":1,"repMin":null,"repMax":null,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"single-kettlebell-clean-and-press","name":"Single kettlebell clean and press","muscles":["Glutes","Shoulders","Triceps"],"instructions":["Hinge and hike one bell between your legs.","Extend your hips and guide the bell close to your body into the rack. Do not flip it onto your wrist.","Pause in the rack with a straight wrist.","Press overhead, then lower to the rack and return to the hinge. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/single-kettlebell-clean-and-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/383/clean-and-press/"},"alternatives":["double-kettlebell-clean-and-press"],"setMin":3,"setMax":4,"repMin":3,"repMax":6,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"double-kettlebell-front-squat","name":"Double kettlebell front squat","muscles":["Quadriceps","Glutes"],"instructions":["Rack one bell beside each shoulder with straight wrists.","Keep elbows near your trunk and brace your body.","Squat with heels grounded and both bells held in the rack.","Stand with the bells still in the rack. Count one rep for the paired movement."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/double-kettlebell-front-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/kettlebell-front-squat"},"alternatives":["kettlebell-goblet-squat"],"setMin":2,"setMax":3,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":3,"setMax":3,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""},{"exercise":{"slug":"turkish-get-up","name":"Turkish get-up","muscles":["Shoulders","Trunk","Glutes"],"instructions":["Lie on your back with the bell in your right hand, right arm vertical, right knee bent and left leg extended.","Roll to your left elbow while keeping the bell above your shoulder.","Press onto your left hand.","Raise your hips to make space for your left leg.","Sweep the left knee under your hips to a supported kneeling position.","Lift your left hand and align into an upright half-kneel.","Stand. Reverse each step with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/turkish-get-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":null,"setMax":null,"repMin":null,"repMax":null,"optional":true,"circuitGroup":null,"restSeconds":180,"notes":""}]}') ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-5-0','phase-3-day-5',0,'{"exercise":{"slug":"barbell-deadlift","name":"Barbell deadlift","muscles":["Glutes","Hamstrings","Back"],"instructions":["Stand with the bar over midfoot, close to your shins.","Bend at hips and knees to grip the bar and brace your trunk.","Push through the floor and stand with the bar close to your legs.","Return the bar by moving your hips back, then bending your knees."],"equipment":"Barbell","loadBasis":"total","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/barbell-deadlift.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/6/deadlift/"},"alternatives":["barbell-back-squat"],"setMin":1,"setMax":1,"repMin":null,"repMax":null,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-5-1','phase-3-day-5',1,'{"exercise":{"slug":"single-kettlebell-clean-and-press","name":"Single kettlebell clean and press","muscles":["Glutes","Shoulders","Triceps"],"instructions":["Hinge and hike one bell between your legs.","Extend your hips and guide the bell close to your body into the rack. Do not flip it onto your wrist.","Pause in the rack with a straight wrist.","Press overhead, then lower to the rack and return to the hinge. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/single-kettlebell-clean-and-press.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.acefitness.org/resources/everyone/exercise-library/383/clean-and-press/"},"alternatives":["double-kettlebell-clean-and-press"],"setMin":3,"setMax":4,"repMin":3,"repMax":6,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-5-2','phase-3-day-5',2,'{"exercise":{"slug":"double-kettlebell-front-squat","name":"Double kettlebell front squat","muscles":["Quadriceps","Glutes"],"instructions":["Rack one bell beside each shoulder with straight wrists.","Keep elbows near your trunk and brace your body.","Squat with heels grounded and both bells held in the rack.","Stand with the bells still in the rack. Count one rep for the paired movement."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":2,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/double-kettlebell-front-squat.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.nasm.org/resource-center/exercise-library/kettlebell-front-squat"},"alternatives":["kettlebell-goblet-squat"],"setMin":2,"setMax":3,"repMin":6,"repMax":10,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-5-3','phase-3-day-5',3,'{"exercise":{"slug":"two-hand-kettlebell-swing","name":"Two-hand kettlebell swing","muscles":["Glutes","Hamstrings"],"instructions":["Place the bell in front of you and hinge to grip it with both hands.","Hike it back between your thighs with a stable back.","Extend your hips to let the bell float to chest height. Do not lift with your arms.","Let the bell fall and hinge again as it returns between your thighs."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":false,"instructionVersion":1,"image":"/assets/exercises/two-hand-kettlebell-swing.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":3,"setMax":3,"repMin":8,"repMax":12,"optional":false,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;
INSERT INTO PlanExercise (id,templateId,"order",payload) VALUES ('phase-3-day-5-4','phase-3-day-5',4,'{"exercise":{"slug":"turkish-get-up","name":"Turkish get-up","muscles":["Shoulders","Trunk","Glutes"],"instructions":["Lie on your back with the bell in your right hand, right arm vertical, right knee bent and left leg extended.","Roll to your left elbow while keeping the bell above your shoulder.","Press onto your left hand.","Raise your hips to make space for your left leg.","Sweep the left knee under your hips to a supported kneeling position.","Lift your left hand and align into an upright half-kneel.","Stand. Reverse each step with control. Repeat on the other side."],"equipment":"Kettlebell","loadBasis":"per-implement","equipmentCount":1,"unilateral":true,"instructionVersion":1,"image":"/assets/exercises/turkish-get-up.webp","reviewStatus":"visual-review-passed","techniqueSource":"https://www.strongfirst.com/achieve/sinister/"},"alternatives":[],"setMin":null,"setMax":null,"repMin":null,"repMax":null,"optional":true,"circuitGroup":null,"restSeconds":180,"notes":""}') ON CONFLICT(id) DO UPDATE SET payload=excluded.payload;